// One accounts-receivable ageing report for the whole ledger: every client who
// still owes money, split by how late each invoice is.
const brand = $('Your company details').first().json;
const today = new Date(new Date().toISOString().slice(0, 10));
const DAY = 24 * 60 * 60 * 1000;

const money = (n) => new Intl.NumberFormat('en-IE', {
  style: 'currency',
  currency: brand.currency || 'EUR',
}).format(Number(n) || 0);

// The order an accountant reads them in.
const BUCKETS = ['Not yet due', '1-30 days', '31-60 days', '61-90 days', '90+ days'];
const bucketFor = (dueDate) => {
  const days = Math.floor((today - new Date(String(dueDate).slice(0, 10))) / DAY);
  if (days <= 0) return BUCKETS[0];
  if (days <= 30) return BUCKETS[1];
  if (days <= 60) return BUCKETS[2];
  if (days <= 90) return BUCKETS[3];
  return BUCKETS[4];
};

// $input.all() is the documented Code node API. `items` is legacy and hands you
// undefined entries when the node above returned nothing, which crashes the run
// on the first property access.
const open = $input.all()
  .map((i) => i.json)
  .filter(Boolean)
  // Invoice Ninja keeps paid invoices in the same list. What is still owed is
  // `balance`, never `amount` - a part-paid invoice carries both.
  .filter((inv) => Number(inv.balance) > 0 && inv.due_date);

const byClient = new Map();
for (const inv of open) {
  // `include: client` fills inv.client. Without it there is still an id to group by.
  const name = inv.client?.display_name || inv.client?.name || `Client ${inv.client_id}`;
  if (!byClient.has(name)) {
    byClient.set(name, {
      name,
      total: 0,
      oldestDays: 0,
      buckets: Object.fromEntries(BUCKETS.map((b) => [b, 0])),
    });
  }
  const row = byClient.get(name);
  const owed = Number(inv.balance);
  const late = Math.max(0, Math.floor((today - new Date(String(inv.due_date).slice(0, 10))) / DAY));
  row.total += owed;
  row.oldestDays = Math.max(row.oldestDays, late);
  row.buckets[bucketFor(inv.due_date)] += owed;
}

const clients = [...byClient.values()].sort((a, b) => b.total - a.total);
const columnTotal = (b) => clients.reduce((sum, c) => sum + c.buckets[b], 0);
const grandTotal = clients.reduce((sum, c) => sum + c.total, 0);
const overdueTotal = grandTotal - columnTotal(BUCKETS[0]);
const asOf = today.toISOString().slice(0, 10);
const accent = brand.accentColour || '#0b6b57';

const esc = (s) => String(s).replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const cell = (v) => (v ? money(v) : '<span class="zero">-</span>');

const rows = clients.map((c) => `
      <tr>
        <td class="name">${esc(c.name)}${c.oldestDays > 90 ? ' <span class="flag">90+ days</span>' : ''}</td>
        ${BUCKETS.map((b) => `<td class="num">${cell(c.buckets[b])}</td>`).join('')}
        <td class="num total">${money(c.total)}</td>
      </tr>`).join('');

const html = `<!doctype html>
<html><head><meta charset="utf-8"><title>Accounts receivable ${asOf}</title>
<style>
  @page { size: A4 landscape; margin: 16mm 14mm; }
  body { font: 12px/1.5 -apple-system, "Segoe UI", Helvetica, Arial, sans-serif; color: #1c1c1c; }
  header { border-bottom: 3px solid ${accent}; padding-bottom: 10px; margin-bottom: 18px; }
  h1 { font-size: 20px; margin: 0 0 2px; color: ${accent}; }
  .sub { color: #555; }
  .cards { display: flex; gap: 10px; margin-bottom: 18px; }
  .card { flex: 1; border: 1px solid #e3e3e3; border-radius: 6px; padding: 10px 12px; }
  .card .k { color: #666; font-size: 11px; text-transform: uppercase; letter-spacing: .04em; }
  .card .v { font-size: 18px; font-weight: 600; margin-top: 2px; }
  table { width: 100%; border-collapse: collapse; }
  th, td { padding: 7px 8px; border-bottom: 1px solid #ececec; }
  th { text-align: right; font-size: 11px; text-transform: uppercase; letter-spacing: .04em; color: #666; }
  th:first-child, td.name { text-align: left; }
  td.num { text-align: right; font-variant-numeric: tabular-nums; }
  td.total, tfoot td { font-weight: 600; }
  tfoot td { border-top: 2px solid ${accent}; border-bottom: none; }
  .zero { color: #bbb; }
  .flag { background: #fdecea; color: #a4291c; border-radius: 3px; padding: 1px 5px; font-size: 10px; }
  footer { margin-top: 20px; color: #666; font-size: 11px; }
</style></head>
<body>
  <header>
    <h1>Accounts receivable &mdash; ${esc(brand.companyName || 'Your company')}</h1>
    <div class="sub">Ageing as at ${asOf} &middot; ${esc(brand.companyAddress || '')}</div>
  </header>
  <div class="cards">
    <div class="card"><div class="k">Outstanding</div><div class="v">${money(grandTotal)}</div></div>
    <div class="card"><div class="k">Overdue</div><div class="v">${money(overdueTotal)}</div></div>
    <div class="card"><div class="k">Over 90 days</div><div class="v">${money(columnTotal(BUCKETS[4]))}</div></div>
    <div class="card"><div class="k">Clients</div><div class="v">${clients.length}</div></div>
  </div>
  <table>
    <thead><tr><th>Client</th>${BUCKETS.map((b) => `<th>${b}</th>`).join('')}<th>Total</th></tr></thead>
    <tbody>${rows}
    </tbody>
    <tfoot><tr><td>Total</td>${BUCKETS.map((b) => `<td class="num">${money(columnTotal(b))}</td>`).join('')}<td class="num">${money(grandTotal)}</td></tr></tfoot>
  </table>
  <footer>${esc(brand.footerNote || '')}</footer>
</body></html>`;

return [{
  json: {
    html,
    asOf,
    clientCount: clients.length,
    invoiceCount: open.length,
    grandTotal,
    grandTotalFormatted: money(grandTotal),
    overdueTotalFormatted: money(overdueTotal),
  },
}];

